 const enterDemo=()=>{setShowEntry(false);setShowOpening(false);setView("home");window.scrollTo({top:0,behavior:"smooth"})};
 const acceptAccount=(user:AccountSession)=>{setAccount(user);setShowAuth(false);setShowEntry(false);setShowOpening(false);writeSaved("leelaEntrySeen","true");const memory=user.memory||{};if(memory.name)setKidName(memory.name);if(memory.mood)setKidMood(memory.mood);if(memory.favoriteAnimal)setKidAnimal(memory.favoriteAnimal);if(memory.favoriteActivity)setKidActivity(memory.favoriteActivity);if(memory.goodDeeds)setGoodDeeds(memory.goodDeeds);if(memory.treasures)setCollectedTreasures(memory.treasures);if(memory.savedStories)setSaved(memory.savedStories);if(typeof memory.dailyAdventureDone==="boolean")setAdventureDone(memory.dailyAdventureDone);tell("Welcome back to Leela.")};
